public class GJChronology_getInstance_TriageGen2Test {

    @Test
    public void testGetInstance_DefaultCutover_UTC() {
        // Tests the branch where gregorianCutover is null and zone is UTC
        GJChronology chrono = GJChronology.getInstance(DateTimeZone.UTC, null, 4);
        assertNotNull(chrono);
        assertEquals(DateTimeZone.UTC, chrono.getZone());
    }

    @Test
    public void testGetInstance_DefaultCutover_NonUTC() {
        // Tests the branch where gregorianCutover is null and zone is not UTC
        DateTimeZone zone = DateTimeZone.forID("America/New_York");
        GJChronology chrono = GJChronology.getInstance(zone, null, 4);
        assertNotNull(chrono);
        assertEquals(zone, chrono.getZone());
    }

    @Test(expected = IllegalArgumentException.class)
    public void testGetInstance_WithCutover_ThrowsException() {
        // The provided source code contains a hardcoded 'if (true)' which 
        // always throws IllegalArgumentException when gregorianCutover is not null.
        // This test ensures that branch is covered.
        ReadableInstant cutover = new Instant(0);
        GJChronology.getInstance(DateTimeZone.UTC, cutover, 4);
    }

    @Test
    public void testGetInstance_CacheHit_UTC() {
        // Tests the branch where the chronology is found in the cache
        // Since the code is synchronized and uses a static cache, 
        // we call it twice with same params. 
        // Note: Due to the 'if(true)' bug in the provided source, 
        // we can only reach the cache if gregorianCutover is null.

        GJChronology first = GJChronology.getInstance(DateTimeZone.UTC, null, 4);
        GJChronology second = GJChronology.getInstance(DateTimeZone.UTC, null, 4);

        assertEquals("Should return cached instance", first, second);
    }

    @Test
    public void testGetInstance_CacheHit_NonUTC() {
        // Tests the branch where the chronology is found in the cache for non-UTC
        DateTimeZone zone = DateTimeZone.forID("Europe/London");

        GJChronology first = GJChronology.getInstance(zone, null, 4);
        GJChronology second = GJChronology.getInstance(zone, null, 4);

        assertEquals("Should return cached instance", first, second);
    }

    @Test
    public void testGetInstance_DifferentMinDaysInFirstWeek_CreatesNew() {
        // Tests that different minDaysInFirstWeek results in a different instance (not a cache hit)
        DateTimeZone zone = DateTimeZone.UTC;

        GJChronology chrono1 = GJChronology.getInstance(zone, null, 4);
        GJChronology chrono2 = GJChronology.getInstance(zone, null, 5);

        assertNotNull(chrono1);
        assertNotNull(chrono2);
        // They should not be the same instance because minDaysInFirstWeek differs
        // However, the code logic for equality in cache check is:
        // if (minDaysInFirstWeek == chrono.getMinimumDaysInFirstWeek() && ...)
        // So if they differ, it proceeds to create a new one.
    }
}
